console.log('[forum-delete] Script loaded'); document.addEventListener('DOMContentLoaded', function () { console.log('[forum-delete] DOM ready'); document.addEventListener('click', function (e) { if (e.target.closest('.delete-post-btn')) { console.log('[forum-delete] Delete button clicked'); const btn = e.target.closest('.delete-post-btn'); const postId = btn.getAttribute('data-post-id'); console.log('[forum-delete] postId:', postId); if (!confirm('Tem certeza que deseja deletar esta mensagem')) { console.log('[forum-delete] Delete cancelled'); return } fetch(`/post/${postId}`, { method: 'DELETE', headers: { 'HX-Request': 'true' } }).then(r => { console.log('[forum-delete] Response status:', r.status); if (r.status === 204) { const card = btn.closest('.card'); if (card) { card.remove(); console.log('[forum-delete] Post card removed from DOM') } else { console.error('[forum-delete] Could not find card element') } } else { console.error('[forum-delete] Unexpected status:', r.status); alert('Erro ao deletar mensagem') } }).catch(err => console.error('[forum-delete] Error:', err)) } }); });
